"""Таблицы в статьях: ключ — адрес статьи.

after — номер раздела H2 (с 1), в конец которого встаёт таблица; caption — подпись; head — шапка;
rows — строки (первая ячейка — заголовок строки); note — необязательная сноска под таблицей.
Цифры в таблицах сверены с текстом статьи и разделами сайта; цены — средние по рынку, «от».
"""

ARTICLE_TABLES = {}


def T(after, caption, head, rows, note=None):
    return {"after": after, "caption": caption, "head": head, "rows": rows, **({"note": note} if note else {})}


